create table if not exists public.buildpulse_social_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.buildpulse_social_posts(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,parent_id uuid references public.buildpulse_social_comments(id) on delete cascade,body text not null check(char_length(body) between 1 and 2000),status text not null default 'published' check(status in ('published','hidden','removed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.buildpulse_social_comments enable row level security;revoke all on public.buildpulse_social_comments from anon,authenticated;grant all on public.buildpulse_social_comments to service_role;
create index if not exists idx_bp_social_comments_post on public.buildpulse_social_comments(post_id,created_at asc);create index if not exists idx_bp_social_comments_author on public.buildpulse_social_comments(author_id,created_at desc);